BEGIN;
-- Test sessions are MFA-verified (aal2) unless a test clears this; admin authority requires it.
SELECT pg_catalog.set_config('request.jwt.claim', '{"aal":"aal2"}', true);
SELECT plan(25);
INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at) VALUES
('e1900000-0000-4000-8000-000000000001','authenticated','authenticated','commerce-admin@example.test','{}',now(),now()),
('e1900000-0000-4000-8000-000000000002','authenticated','authenticated','commerce-owner@example.test','{}',now(),now()),
('e1900000-0000-4000-8000-000000000003','authenticated','authenticated','commerce-other@example.test','{}',now(),now());
INSERT INTO public.user_roles(user_id,role,granted_by) VALUES('e1900000-0000-4000-8000-000000000001','admin','e1900000-0000-4000-8000-000000000001');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1900000-0000-4000-8000-000000000001',true);
SELECT set_config('c.course',public.admin_save_course_content('commerce-check','en','Paid course','Fixture','',49900,'','beginner',true)::text,true);
SELECT set_config('request.jwt.claim.sub','e1900000-0000-4000-8000-000000000002',true);
SELECT set_config('c.order',public.learner_create_order(current_setting('c.course')::uuid,'en')::text,true);
SELECT is(public.learner_create_order(current_setting('c.course')::uuid,'en'),current_setting('c.order')::uuid,'repeated start reuses pending order');
SELECT is((SELECT total_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),49900::bigint,'price determined server-side');
SELECT is((SELECT count(*)::int FROM public.order_items WHERE order_id=current_setting('c.order')::uuid),1,'one immutable item snapshot');
SELECT throws_ok($$UPDATE public.orders SET status='paid'$$,'42501',NULL,'learner cannot mark paid');
SELECT throws_ok($$SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'EGP','paid','event')$$,'42501',NULL,'learner cannot call settlement');
SELECT throws_ok($$SELECT public.learner_create_order(current_setting('c.course')::uuid,'ar')$$,'P0002',NULL,'missing exact-locale publication denied');
SELECT set_config('request.jwt.claim.sub','e1900000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::int FROM public.orders),0,'another account cannot read orders');
SELECT is((SELECT count(*)::int FROM public.order_items),0,'another account cannot read item snapshots');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.enrollments WHERE user_id='e1900000-0000-4000-8000-000000000002'),0,'pending order grants no access');
SET LOCAL ROLE service_role;
SELECT public.commerce_bind_session(current_setting('c.order')::uuid,'0123456789abcdef01234567','https://payments.kashier.io/session/0123456789abcdef01234567?mode=test',49900);
SELECT throws_ok($$SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',1,'EGP','paid','wrong-amount')$$,'23514',NULL,'wrong amount rejected');
SELECT throws_ok($$SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'USD','paid','wrong-currency')$$,'23514',NULL,'wrong currency rejected');
SELECT throws_ok($$SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'wrong-session','provider',49900,'EGP','paid','wrong-session')$$,'23514',NULL,'wrong session rejected');
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'EGP','paid','capture');
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'EGP','paid','capture');
RESET ROLE;
SELECT is((SELECT status FROM public.orders WHERE id=current_setting('c.order')::uuid),'paid','verified capture marks paid');
SELECT is((SELECT count(*)::int FROM public.enrollments WHERE user_id='e1900000-0000-4000-8000-000000000002'),1,'duplicate confirmation grants once');
SELECT is((SELECT grant_source FROM public.enrollments WHERE user_id='e1900000-0000-4000-8000-000000000002'),'paid','paid source preserved');
SELECT is((SELECT count(*)::int FROM public.payment_events),1,'verified receipt deduplicates');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1900000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.learner_create_order(current_setting('c.course')::uuid,'en')$$,'23514',NULL,'already enrolled cannot buy twice');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'EGP','refunded','refund');
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234567','provider',49900,'EGP','paid','late-capture');
RESET ROLE;
SELECT is((SELECT status FROM public.orders WHERE id=current_setting('c.order')::uuid),'refunded','refund cannot be undone by late capture');
SELECT is((SELECT status FROM public.enrollments WHERE user_id='e1900000-0000-4000-8000-000000000002'),'refunded','full refund revokes paid access');
SELECT ok((SELECT refund_confirmed_at IS NOT NULL AND revoked_by IS NULL FROM public.enrollments WHERE user_id='e1900000-0000-4000-8000-000000000002'),'automatic refund does not impersonate an administrator');
SELECT ok(NOT has_function_privilege('anon','public.learner_create_order(uuid,text)','EXECUTE'),'anonymous order creation denied');
SELECT ok(NOT has_table_privilege('authenticated','public.payments','SELECT'),'provider session records stay private');
SELECT ok(NOT has_table_privilege('authenticated','public.payment_events','SELECT'),'payment event records stay private');
SELECT ok(NOT has_function_privilege('authenticated','public.commerce_get_order(uuid)','EXECUTE') AND NOT has_function_privilege('authenticated','public.commerce_bind_session(uuid,text,text,bigint)','EXECUTE') AND NOT has_function_privilege('authenticated','public.commerce_confirm_order(uuid,text,text,bigint,text,text,text)','EXECUTE'),'privileged commerce functions stay service-only');
SELECT ok(has_function_privilege('service_role','public.commerce_confirm_order(uuid,text,text,bigint,text,text,text)','EXECUTE'),'settlement is available to the trusted server role');
SELECT * FROM finish();ROLLBACK;
